import{_ as a,o as i,c as e,a4 as n}from"./chunks/framework.vNSRaLQv.js";const k=JSON.parse('{"title":"U-Boot 启动参数探索","description":"","frontmatter":{"title":"U-Boot 启动参数探索","date":"2026-07-25T00:00:00.000Z"},"headers":[],"relativePath":"posts/06_uboot_bootargs_exploration.md","filePath":"posts/06_uboot_bootargs_exploration.md"}'),t={name:"posts/06_uboot_bootargs_exploration.md"};function o(p,s,l,d,h,r){return i(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="u-boot-启动参数探索" tabindex="-1">U-Boot 启动参数探索 <a class="header-anchor" href="#u-boot-启动参数探索" aria-label="Permalink to &quot;U-Boot 启动参数探索&quot;">​</a></h1><h2 id="u-boot-环境变量" tabindex="-1">U-Boot 环境变量 <a class="header-anchor" href="#u-boot-环境变量" aria-label="Permalink to &quot;U-Boot 环境变量&quot;">​</a></h2><p>通过 <code>printenv</code> 查看：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>arch=arm</span></span>
<span class="line"><span>board=zx296716_square</span></span>
<span class="line"><span>bootcmd=bootsys</span></span>
<span class="line"><span>bootdelay=0</span></span>
<span class="line"><span>cpu=armv8</span></span>
<span class="line"><span>ethact=dwmac.5200000</span></span>
<span class="line"><span>ipaddr=192.168.1.22</span></span>
<span class="line"><span>serverip=192.168.1.24</span></span>
<span class="line"><span>loadaddr=0x40008000</span></span>
<span class="line"><span>fdtcontroladdr=0x48000000</span></span></code></pre></div><h2 id="bootargs-构建机制" tabindex="-1">Bootargs 构建机制 <a class="header-anchor" href="#bootargs-构建机制" aria-label="Permalink to &quot;Bootargs 构建机制&quot;">​</a></h2><p><code>bootsys</code> 是 C 函数，不是 u-boot 命令。它用 <code>sprintf</code> 拼接 bootargs：</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;">// u-boot 二进制中的字符串模板</span></span>
<span class="line"><span style="--shiki-light:#B5695977;--shiki-dark:#C98A7D77;">&quot;</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;">setenv bootargs root=/dev/ram0 rw initrd=0x</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;">%x</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;">,0x</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;">%x</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> boardtype=0x</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;">%x</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> \\</span></span>
<span class="line"><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;">  console=ttyS0,115200n8 \${othbootargs} stmmaceth=chain_mode:1 </span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;">\\</span></span>
<span class="line"><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;">  kgdboc=ttyS0,115200 loglevel=3 swiotlb=0x800</span><span style="--shiki-light:#B5695977;--shiki-dark:#C98A7D77;">&quot;</span></span></code></pre></div><p>后续追加参数（从 conf 分区和硬件读取）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>androidboot.hardware=zxic</span></span>
<span class="line"><span>androidboot.selinux=disabled</span></span>
<span class="line"><span>boot_revision=0006</span></span>
<span class="line"><span>LogoDataAddr=0x74000000</span></span>
<span class="line"><span>WorkMode=</span></span></code></pre></div><h2 id="踩坑-othbootargs-是死字符串" tabindex="-1">踩坑：othbootargs 是死字符串 <a class="header-anchor" href="#踩坑-othbootargs-是死字符串" aria-label="Permalink to &quot;踩坑：othbootargs 是死字符串&quot;">​</a></h2><p><code>\${othbootargs}</code> 在 u-boot 命令行中会展开变量，但在 C 代码的 <code>sprintf</code> 中是字面量。</p><p><strong>测试：</strong> 在 u-boot 中 <code>setenv othbootargs cma=64M</code>，启动后 <code>/proc/cmdline</code> 中显示 <code>\${othbootargs}</code> 而不是 <code>cma=64M</code>。</p><p><strong>原因：</strong> <code>bootsys</code> 函数用 <code>sprintf</code> 拼接字符串，不调用 <code>getenv(&quot;othbootargs&quot;)</code>。</p><p><strong>结论：</strong> env 分区的 <code>othbootargs</code> 无法影响 bootargs。</p><h2 id="踩坑-env-分区格式" tabindex="-1">踩坑：env 分区格式 <a class="header-anchor" href="#踩坑-env-分区格式" aria-label="Permalink to &quot;踩坑：env 分区格式&quot;">​</a></h2><p>标准 u-boot env 格式：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>[4字节 CRC32] [key=value\\0 key=value\\0 ... \\0\\0]</span></span></code></pre></div><p>ZTE 的 env 分区（mmcblk0p5）内容：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>bootcmd=bootp; setenv bootargs root=/dev/nfs ...</span></span>
<span class="line"><span>bootdelay=5</span></span>
<span class="line"><span>baudrate=115200</span></span>
<span class="line"><span>upgrade_step=1</span></span>
<span class="line"><span>force_auto_update=false</span></span></code></pre></div><p><code>setenv</code>/<code>printenv</code> 在 u-boot 控制台能用，但 <code>bootsys</code> 不读 env 变量。</p><h2 id="u-boot-可用命令" tabindex="-1">U-Boot 可用命令 <a class="header-anchor" href="#u-boot-可用命令" aria-label="Permalink to &quot;U-Boot 可用命令&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>bootsys    - 正常启动</span></span>
<span class="line"><span>safe       - 进入 safe mode (recovery)</span></span>
<span class="line"><span>upgrade    - 刷写分区</span></span>
<span class="line"><span>tftpboot   - TFTP 下载到内存</span></span>
<span class="line"><span>mmc        - eMMC 读写</span></span>
<span class="line"><span>bootm      - 从内存启动镜像</span></span></code></pre></div><h2 id="网络配置" tabindex="-1">网络配置 <a class="header-anchor" href="#网络配置" aria-label="Permalink to &quot;网络配置&quot;">​</a></h2><p>u-boot 网络需要和电脑在同一网段：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">setenv</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> ipaddr</span><span style="--shiki-light:#2F798A;--shiki-dark:#4C9A91;"> 192.168.1.22</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">setenv</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> serverip</span><span style="--shiki-light:#2F798A;--shiki-dark:#4C9A91;"> 192.168.1.24</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">setenv</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> gatewayip</span><span style="--shiki-light:#2F798A;--shiki-dark:#4C9A91;"> 192.168.1.1</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">setenv</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> netmask</span><span style="--shiki-light:#2F798A;--shiki-dark:#4C9A91;"> 255.255.255.0</span></span></code></pre></div><p>电脑有线网卡需要配置到 192.168.1.x 网段：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">sudo</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> ip</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> addr</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> add</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> 192.168.1.24/24</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> dev</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> enxdc3262cf0be6</span></span></code></pre></div>`,27)])])}const g=a(t,[["render",o]]);export{k as __pageData,g as default};
